import sys

def merge_rec(l1, l2):
    if not l1 or not l2:
        return l1 or l2
    if l1[0] <= l2[0]:
        return [l1[0]] + merge_rec(l1[1:], l2)
    else:
        return [l2[0]] + merge_rec(l1, l2[1:])

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if not data or not data[0].strip():
        sys.exit(0)
    m_n = data[0].split()
    m, n = int(m_n[0]), int(m_n[1])
    l1 = list(map(int, data[1].split())) if m > 0 and len(data) > 1 else []
    l2 = list(map(int, data[2].split())) if n > 0 and len(data) > 2 else []
    print(' '.join(map(str, merge_rec(l1, l2))))
